6	module sgen_cordic #(
7	  parameter gp_mode_rot_vec            = 0,
8	  parameter gp_impl_unrolled_iterative = 0,
9	  parameter gp_nr_iter                 = 16,
10	  parameter gp_angle_width             = 16,
11	  parameter gp_angle_depth             = 16,
12	  parameter gp_xy_width                = 8,
13	  parameter gp_z_width                 = 8
14	) (
15	  input  wire                          i_rst_an,
16	  input  wire                          i_ena,
17	  input  wire                          i_clk,
18	  input  wire signed [gp_xy_width-1:0] i_x,
19	  input  wire signed [gp_xy_width-1:0] i_y,
20	  input  wire signed [gp_z_width-1 :0] i_z,
21	  output wire signed [gp_xy_width-1:0] o_x,
22	  output wire signed [gp_xy_width-1:0] o_y,
23	  output wire signed [gp_z_width-1 :0] o_z,
24	  output wire                          o_done
25	);
26	// -------------------------------------------------------------------
27	  // CONSTANT DECLARATION
28	  localparam c_ext_bits          = $clog2(gp_nr_iter);
29	  localparam c_xy_internal_width = gp_xy_width + c_ext_bits;
30	  localparam c_z_internal_width  = gp_z_width;
31	  localparam c_iter_width        = (!gp_impl_unrolled_iterative) ? c_ext_bits : 0;
32	  // WIRE DECLARATION
33	  wire signed [gp_angle_width-1:0] atan_lut [0:gp_angle_depth-1];
34	// -------------------------------------------------------------------
35	  `include "atan_lut.v"
36	// -------------------------------------------------------------------
37	  
38	  genvar i;
39	  generate
40	    if (gp_impl_unrolled_iterative)
41	      begin: g_cordic_unrolled
42	        // WIRE DECLARATION
43	        wire signed [c_xy_internal_width-1:0] x_init;
44	        wire signed [c_xy_internal_width-1:0] y_init;
45	        wire signed [c_z_internal_width-1 :0] z_init;
46	        wire                                  d [0:gp_nr_iter-1];
47	        wire signed [c_xy_internal_width-1:0] x [0:gp_nr_iter-1];
48	        wire signed [c_xy_internal_width-1:0] y [0:gp_nr_iter-1];
49	        wire signed [c_z_internal_width-1 :0] z [0:gp_nr_iter-1];
50	
51		// INITIALIZATION
52	        assign x_init = i_x<<<c_ext_bits;
53		assign y_init = i_y<<<c_ext_bits;
54		assign z_init = i_z;
55		// CORDIC UNROLLED ITERATIONS
56	        for (i=0; i<gp_nr_iter; i=i+1)
57	          begin: g_cordic_iterations
58	            if (i==0)
59	    	      begin: g_cordic_init
60	    	        if (gp_mode_rot_vec)
61	    	          begin: g_d_init_rot
62	    	            assign d[i] = (z_init[c_z_internal_width-1] == 0)  ? 1'b1 : 1'b0;
63	    	          end
64	    	        else
65	    	          begin: g_d_init_vec
66	    	            assign d[i] = (y_init[c_xy_internal_width-1] == 1) ? 1'b1 : 1'b0;
67	    	          end
68	    	        // CORDIC ALGORITHM
69	    	        assign x[i] = (d[i]) ? x_init - y_init      : x_init + y_init;
70	    	        assign y[i] = (d[i]) ? y_init + x_init      : y_init - x_init;
71	    	        assign z[i] = (d[i]) ? z_init - atan_lut[i] : z_init + atan_lut[i];
72	    	      end
73	    	    else
74	    	      begin
75	    	        if (gp_mode_rot_vec)
76	    	          begin: g_d_rot
77	    	            assign d[i] = (z[i-1][c_z_internal_width-1] == 0)  ? 1'b1 : 1'b0;
78	    	          end
79	    	        else
80	    	          begin: g_d_vec
81	    	            assign d[i] = (y[i-1][c_xy_internal_width-1] == 1) ? 1'b1 : 1'b0;
82	    	          end	  
83	    	        // CORDIC ALGORITHM
84	    	        assign x[i] = (d[i]) ? x[i-1] - (y[i-1] >>> i) : x[i-1] + (y[i-1] >>> i);
85	    	        assign y[i] = (d[i]) ? y[i-1] + (x[i-1] >>> i) : y[i-1] - (x[i-1] >>> i);
86	    	        assign z[i] = (d[i]) ? z[i-1] - atan_lut[i]    : z[i-1] + atan_lut[i];
87	    	    end	
88	          end//FOR_CORDIC_UNROLLED
89	
90		// OUTPUT ASSIGNMENT
91		assign o_x = x[gp_nr_iter-1];        
92	        assign o_y = y[gp_nr_iter-1];
93	        assign o_z = z[gp_nr_iter-1];
94	      end//IF_CORDIC_ROT
95	  endgenerate
96	  
97	  generate
98	    if (!gp_impl_unrolled_iterative)
99	      begin: g_cordic_iterative
100	        // WIRE DECLARATION
101	        wire signed [c_xy_internal_width-1:0] w_x;
102	        wire signed [c_xy_internal_width-1:0] w_y;
103	        wire signed [c_z_internal_width-1 :0] w_z;
104	        wire signed [c_xy_internal_width-1:0] x;
105	        wire signed [c_xy_internal_width-1:0] y;
106	        wire signed [c_z_internal_width-1 :0] z;
107	        // REGISTER DECLARATION
108		reg  signed [c_xy_internal_width-1:0] r_x;
109	        reg  signed [c_xy_internal_width-1:0] r_y;
110	        reg  signed [c_z_internal_width-1 :0] r_z;
111	        reg         [c_iter_width-1       :0] r_count_iter;
112	        // ITERATION COUNTER
113	        always @(posedge i_clk or negedge i_rst_an)
114	          begin: p_iter_count
115	            if (!i_rst_an)
116	              begin
117	      	        r_count_iter <= {c_iter_width{1'b1}};
118	      	      end
119	            else if (i_ena)
120	              begin
121	      	        if (r_count_iter < gp_nr_iter)
122	      	          r_count_iter <= r_count_iter + 1'b1;
123	      	        else
124	      	          r_count_iter <= {c_iter_width{1'b0}};
125	      	      end
126	          end
127	        // CORDIC REG-BANK
128	        always @(posedge i_clk or negedge i_rst_an)
129	          begin: p_cordic_iter_regbank
130	            if (!i_rst_an)
131	              begin
132	      	        r_x <= 'd0;
133	      	        r_y <= 'd0;
134	      	        r_z <= 'd0;
135	      	      end
136	            else if (i_ena)
137	              begin
138	      	        if (r_count_iter>(gp_nr_iter-1))
139	      	          begin
140	      	            r_x <= i_x<<<c_ext_bits;
141	      	            r_y <= i_y<<<c_ext_bits;
142	      	            r_z <= i_z;
143	      	          end
144	      	        else
145	      	          begin
146	      	            r_x <= x;
147	      	            r_y <= y;
148	      	            r_z <= z;
149	      	          end	  
150	      	      end
151	          end
152	        
153	        // RESOURCE SHARING
154	        assign w_x = (gp_mode_rot_vec) ? ( (r_z[c_z_internal_width-1])  ? -r_x :  r_x )   // ROTATION MODE
155		                               : ( (r_y[c_xy_internal_width-1]) ?  r_x : -r_x );  // VECTORING MODE
156	        assign w_y = (gp_mode_rot_vec) ? ( (r_z[c_z_internal_width-1])  ?  r_y : -r_y )   // ROTATION MODE
157		                               : ( (r_y[c_xy_internal_width-1]) ? -r_y :  r_y );  // VECTORING MODE      
158	        assign w_z = (gp_mode_rot_vec) ? ( (r_z[c_z_internal_width-1])  ?  atan_lut[r_count_iter] : -atan_lut[r_count_iter])   // ROTATION MODE
159	                                       : ( (r_y[c_xy_internal_width-1]) ? -atan_lut[r_count_iter] :  atan_lut[r_count_iter]);  // VECTORING MODE
160	        
161		// CORDIC ALGORITHM - ITERATIVE RESOURCE SHARING
162	        assign x = r_x + (w_y >>> r_count_iter);
163	        assign y = r_y + (w_x >>> r_count_iter);
164	        assign z = r_z + w_z;
165		
166		// OUTPUT ASSIGNMENT
167		assign o_x = x;        
168	        assign o_y = y;
169	        assign o_z = z;	
170	      end//IF_CORDIC_VEC
171	  endgenerate  
172	  
173	endmodule
