180	module cordic_gain #(
181	  parameter gp_mode_rot_vec = 0,
182	  parameter gp_gain_width   = 12,
183	  parameter gp_xy_width     = 8,
184	  parameter gp_xy_owidth    = gp_xy_width+$clog2(gp_gain_width)
185	) (
186	  input  wire signed [gp_xy_width-1 :0] i_cordic_x,
187	  input  wire signed [gp_xy_width-1 :0] i_cordic_y,
188	  output wire signed [gp_xy_owidth-1:0] o_cordic_x,
189	  output wire signed [gp_xy_owidth-1:0] o_cordic_y
190	);
191	// -------------------------------------------------------------------
192	  localparam c_1_gain = $rtoi( 0.607252959138945 * (2.0**(gp_gain_width-1)) );
193	  wire signed [gp_xy_width+gp_gain_width-1:0] x_tmp;
194	  wire signed [gp_xy_width+gp_gain_width-1:0] y_tmp;
195	// -------------------------------------------------------------------  
196	  assign x_tmp = i_cordic_x * c_1_gain;
197		
198	  if (gp_mode_rot_vec)
199	    begin	    	    
200	      assign y_tmp = i_cordic_x * c_1_gain;
201	    end
202	  else
203	    begin
204	      assign y_tmp = 'd0;
205	    end	
206	
207	  // OUTPUT ASSIGNMENT
208	  assign o_cordic_x = x_tmp >>> (gp_gain_width-1);    
209	  assign o_cordic_y = y_tmp >>> (gp_gain_width-1);
210	endmodule
