3	// -------------------------------------------------------------------
4	`timescale 1ns/1ps
5	`include "defines.sv"
6	// -------------------------------------------------------------------
7	module filt_cicd_tb;
8	  time CLK_PERIOD = 50;
9	  
10	  reg       i_rst_an;
11	  reg       i_ena;
12	  reg       i_clk;
13	  wire      s_clk;
14	  
15	  reg [`P_INP_DATA_W-1:0] i_data;
16	  wire                 rdy;
17	  wire signed [`P_OUP_DATA_W-1:0] oup_data;
18	  reg                             data_ready;
19	  integer error_count=0;
20	  reg [8*64:1]                    filename_vcd;
21	  // READ-IN MATLAB STIMULI FILE  
22	  reg [8*64:1]                    filename_mat_inp;
23	  integer                         fid_mat_inp;
24	  integer                         status_mat_inp;  
25	  // READ-IN MATLAB RESPONSE FILE
26	  reg [8*64:1]                    filename_mat_oup;
27	  integer                         fid_mat_oup;
28	  integer                         status_mat_oup;
29	  reg signed [`P_OUP_DATA_W-1:0]       o_data_mat;
30	// -------------------------------------------------------------------    
31	  initial
32	    begin
33	           i_rst_an = 1'b1;
34	      #170 i_rst_an = 1'b0;
35	      #205 i_rst_an = 1'b1;
36	    end
37	  
38	  initial
39	    begin
40	           i_ena = 1'b0;
41	      #400 i_ena = 1'b1;
42	    end
43	  
44	  initial i_clk = 1'b0;
45	  always i_clk = #(CLK_PERIOD) ~i_clk;
46	  
47	  assign #1 s_clk = dut.w_sclk;
48	  
49	  initial
50	    begin: TEXTIO_READ_IN
51	      $display("### INFO: RTL Simulation of FIR Filter.");
52	      $display("### Testcase %d", `TESTCASE);
53	      $sformat(filename_mat_inp,"%s%0d%s","./sim/testcases/stimuli/stimuli_tc_",`TESTCASE,"_mat.dat");
54	      $sformat(filename_mat_oup,"%s%0d%s","./sim/testcases/response/response_tc_",`TESTCASE,"_mat.dat");
55	      $display("%s",filename_mat_inp);
56	      fid_mat_inp = $fopen(filename_mat_inp, "r");
57	      fid_mat_oup = $fopen(filename_mat_oup, "r");
58	      if ((fid_mat_inp == `NULL)||(fid_mat_oup == `NULL)) begin
59	        $display("data_file handle was NULL");
60	        $finish;
61	      end
62	      
63	      @(posedge data_ready) 
64	        begin 
65		  $fclose(fid_mat_inp); 
66		  $fclose(fid_mat_oup); 
67	
68		  if (error_count>0)
69	            $display("### INFO: Testcase FAILED");
70	          else
71	            $display("### INFO: Testcase PASSED");
72		    
73	  	  $finish; 
74		end
75	    end
76	    
77	  always @(posedge i_clk)
78	    begin: MATLAB_STIMULI
79	      if (i_rst_an && i_ena)
80	        status_mat_inp = $fscanf(fid_mat_inp,"%d\n", i_data);
81	      else
82	        i_data = 'd0;
83		
84	      if ($feof(fid_mat_inp)) begin
85	        data_ready = 1'b1;
86	      end
87	    end
88	  
89	  always @(negedge s_clk)
90	    begin: MATLAB_RESPONSE
91	      if (i_rst_an && i_ena)
92	        status_mat_oup = $fscanf(fid_mat_oup,"%d\n", o_data_mat);
93	      else
94	        o_data_mat = 'd0;
95	    end
96	
97	  always @(posedge s_clk)
98	    begin
99	      if (i_rst_an && i_ena)
100	        if (oup_data != o_data_mat) 
101		//else
102		  begin 
103		    $error("### RTL = %d, MAT = %d", oup_data, o_data_mat); error_count<= error_count + 1;
104		  end
105	    end
106	      
107	  filt_cicd #(
108	    .gp_decimation_factor (`P_DECIMATION),  
109	    .gp_order		  (`P_ORDER),
110	    .gp_diff_delay	  (`P_DIFF_DELAY),
111	    .gp_phase		  (`P_PHASE),
112	    .gp_inp_width	  (`P_INP_DATA_W),
113	    .gp_oup_width	  ()
114	  ) dut (
115	    .i_rst_an (i_rst_an),
116	    .i_ena    (i_ena),
117	    .i_clk    (i_clk),
118	    .i_data   (i_data),
119	    .o_data   (oup_data)
120	  );
121	
122	`ifdef VCD
123	  initial
124	     begin
125	       $sformat(filename_vcd,"%s%0d%s","filt_cicd_",`TESTCASE,".vcd");
126	       $dumpfile(filename_vcd);
127	       $dumpvars(0,filt_cicd_tb);
128	     end
129	`endif
130	    
131	endmodule
