1	function gen_atan_lut(n_iter, bitwidth)
2	  % This function generates the LUT for the ATAN power-of-two values for the 
3	  % CORDIC algorithm.
4	  % The bit-width shall consider signed fixed-point values despite that all the
5	  % values are positive.
6	  atan_lut = atan(2.^-[0:n_iter-1]);
7	  atan_lut_q = uquant(atan_lut, bitwidth, "s");
8	  atan_lut_s = floor(atan_lut_q.*2^(bitwidth-2));
9	  fid = fopen("atan_lut.v", "w");
10	  for i = 1 : n_iter,
11	    fprintf(fid, "assign atan_lut[%d] =  %d'sd%d;\n", i-1, bitwidth, atan_lut_s(i));
12	  end
13	
14	  fclose(fid);

